import{_ as n,o as r,c as i,ah as a}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"23. März 2026: Satirische Forensik – Das Märchen von der Patientenmilliarde","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/2026-03-23-maerchen-patientenmilliarde.md","filePath":"logbuch/2026-03-23-maerchen-patientenmilliarde.md"}'),s={name:"logbuch/2026-03-23-maerchen-patientenmilliarde.md"};function t(d,e,l,h,u,o){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_23-marz-2026-satirische-forensik-–-das-marchen-von-der-patientenmilliarde" tabindex="-1">23. März 2026: Satirische Forensik – Das Märchen von der Patientenmilliarde <a class="header-anchor" href="#_23-marz-2026-satirische-forensik-–-das-marchen-von-der-patientenmilliarde" aria-label="Permalink to &quot;23. März 2026: Satirische Forensik – Das Märchen von der Patientenmilliarde&quot;">​</a></h1><p>Neben der harten Recherche zum Wöginger-Rückzug und dem System Hattmannsdorfer haben wir heute eine künstlerische Aufarbeitung der Ära Kurz vorgenommen. Um die „Harte Prosa“ der damaligen Zeit (2017–2019) zu entlarven, haben wir die Geschichte der <strong>Patientenmilliarde</strong> in ein Märchen im Stile der Gebrüder Grimm gegossen.</p><h2 id="vom-wunderknaben-und-der-verschwundenen-milliarde" tabindex="-1">Vom Wunderknaben und der verschwundenen Milliarde <a class="header-anchor" href="#vom-wunderknaben-und-der-verschwundenen-milliarde" aria-label="Permalink to &quot;Vom Wunderknaben und der verschwundenen Milliarde&quot;">​</a></h2><p>Es war einmal, vor gar nicht allzu langer Zeit, in einem Lande namens Austriastan, das von hohen Bergen und noch höheren Schulden umschlossen war. In diesem Lande lebte ein Jüngling mit gar holdem Antlitz und Ohren, so groß, dass er das Gras wachsen und die Umfragen steigen hörte. Man nannte ihn den <strong>Wunderknaben Sebastian</strong>.</p><p>Sebastian trug stets ein azurblaues Gewand und sprach in Versen, die so glatt waren, dass die Wahrheit darauf ausrutschte wie auf frischem Eis. Eines Tages trat er vor das Volk, das unter den Gebrechen des Alters und der Teuerung litt, und verkündete mit silberner Stimme: „Höret her! Ich werde die einundzwanzig Töpfe der Heilung zu einem einzigen großen Kessel verschmelzen. Und wahrlich, ich sage euch: In diesem Kessel wird durch Zauberei eine ganze <strong>Milliarde an Goldstücken</strong> entstehen, die allein den Kranken und Siechen zugutekommen soll!“</p><p>An seiner Seite stand eine getreue Magd namens <strong>Beate von der Kleinen Hand</strong>. Sie war die Hüterin der Zahlen, doch ihre Rechenkunst war von seltsamer Natur. Wenn sie eins und eins zusammenzählte, kam stets das heraus, was der Wunderknabe gerade wünschte. „Es wird eine Gönnung sein!“, rief sie in den Wald hinein, und das Echo antwortete zynisch: „...nung sein ... nung sein“.</p><p>So begannen sie, die Töpfe mit Gewalt zusammenzupressen. Es krachte und schepperte im Gebälk des Reiches. Viele weise Heiler warnten: „Edler Prinz, das Verschmelzen der Töpfe kostet selbst viel Gold, und am Ende wird der Kessel leck sein!“ Doch Sebastian lächelte nur sein schmalstes Lächeln und sprach: „Das ist nur die <strong>Harte Prosa</strong> des Neides. Vertrauet auf mein Licht!“</p><p>Jahre vergingen. Die Töpfe waren nun eins, doch als das Volk herbeieilte, um seinen Anteil an der versprochenen Milliarde abzuholen, fanden sie den Kessel leer vor. Schlimmer noch: Wo früher ein silberner Löffel für jeden war, gab es nun nur noch hölzerne Stäbchen. Die Milliarde war nicht erschienen. Stattdessen hatten sich dunkle Gestalten in schwarzen Kutten um den Kessel versammelt und die Kosten für neue Schlösser und goldene Siegel so hoch getrieben, dass das Gold der Armen darin verbrannte wie trockenes Stroh.</p><p>Als das Volk die Magd Beate fragte: „Wo ist denn nun das versprochene Gold?“, blickte sie gen Himmel und sprach: „Ich sehe es ganz deutlich! Es ist nur ... pointillistisch verteilt! Man muss nur ganz fest daran glauben, dann spürt man den Reichtum in der Ferne.“</p><p>Der Wunderknabe Sebastian aber war zu dieser Zeit schon über die sieben Berge zu einem dunklen Zauberer namens <strong>Thiel</strong> gezogen, um dort in gläsernen Palästen nach noch größerem Golde zu schürfen. Er hinterließ dem Volk nur ein Bild aus lauter kleinen, bunten Punkten. Wenn man von Weitem darauf sah, wirkte es wie eine Milliarde. Doch wenn man näher herantrat, sah man, dass es nur die Tränen der Patienten waren, die im fahlen Licht der Propaganda glitzerten.</p><p>Und wenn sie nicht gestorben sind, dann warten sie noch heute auf die Milliarde – während die „Harte Prosa“ leise durch die leeren Flure der Krankenhäuser weht.</p><hr><p><em>Dieser Text ist nun auch in unserer neuen Sektion „Satirische Forensik“ in der Medien-Abteilung zu finden.</em></p>',13)])])}const g=n(s,[["render",t]]);export{m as __pageData,g as default};
